from typing import *
from collections import deque

class Solution:
    def parse(self, paren_string: str) -> List[int]:
        stack = deque()
        result = []

        for char in paren_string:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack[-1] != '(':
                    return []  # Invalid input

                stack.pop()  # Pop off the last element (which was an opening parenthesis)

            else:
                continue

        while stack:
            result.append(len(stack))
            stack.pop()

        return result[::-1]

