        if arr == sorted(arr):
            return True

        # Iterate through the array and check each element
        for i in range(len(arr)):
            if arr[i] > arr[(i + 1) % len(arr)]:
                # Perform right shift operation
                arr = arr[:i] + [arr[(i + 1) % len(arr)], arr[i]] + arr[i+1:]

