    def maxFill(self, grid: List[List[int]], capacity: int) -> int:
        # Initialize variables for counting and filling
        count = 0
        filled = 0

        # Iterate through each row of the grid
        for i in range(len(grid)):
            # Count how many units of water are currently in the current row
            if grid[i][0] == 1:
                count += 1

            # If there's more than one unit of water in the current row, fill the first bucket
            while count > 0 and filled < capacity:
