def do_algebra(operator: List[str], operand: List[int]) -> int:
    # Initialize the result with the first element of the operand list
    result = operand[0]

    # Iterate through each operator in the operator list
    for op in operator:
        if op == '+':
            result += operand[1]  # Add the next element of the operand list to the result
        elif op == '-':
            result -= operand[1]  # Subtract the next element of the operand list from the result
        elif op == '*':
            result *= operand[1]  # Multiply the result by the next element of the operand list
        elif op == '//':
            result //= operand[1]  # Divide the result by the next element of the operand list
        elif op == '**':
            result **= operand[1]  # Raise the result to the power of the next element of the operand list

    return result
