from collections import Counter

def cycpattern_check(a , b):
    # Check if either word is a substring of the other
    if a == b:
        return True
    elif len(b) > len(a):
        return False
    else:
        # Count the frequency of each character in both words
        c1 = Counter(a)
        c2 = Counter(b)

        # If there's at least one common character between the two words,
        # then their rotations are also common characters.
        for char in set(c1.keys() & c2.keys()):
            if c1[char] >= c2[char]:
                return True

        return False
