def bf(planet1, planet2):
    # Check if both planet names are valid
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    # Create a deque for planet positions
    dq = deque()
    dq.append(planet1)
    dq.append(planet2)

    # Initialize variables to keep track of visited planets
    visited = set()

    while dq:
        current_planet = dq.popleft()

        # If the current planet has been visited before, skip it
        if current_planet in visited:
            continue

        # Add the current planet's position to the visited set
        visited.add(current_planet)

        # Append the current planet's name to the result list
        result.append(current_planet)

        # Move to the next planet based on their proximity to the sun
        if current_planet < planet2:
            dq.extend([current_planet + 0.5] * (planet2 - current_planet))
        else:
            dq.extend([current_planet - 0.5] * (current_planet - planet2))

    return tuple(result)

