from collections import deque

def bf(planet1, planet2):
    # Check if both planet names are valid
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    # Initialize an empty list to store tuples of planets
    result = []

    # Use deque for efficient pop from the end
    dq = deque()

    # Add planet1's orbit to the deque
    dq.append((planet1, 0))

    while dq:
        current_planet, distance = dq.popleft()

        # If the current planet's orbit is within the range of planet2, add it to the result
        if current_planet == planet2:
            result.append(current_planet)

        # Add planets with greater distances than current planet's orbit to the deque
        if current_planet != planet2 and distance > 0:
            dq.extend([(current_planet, distance + 1), (planet2, distance)])

    return tuple(result)

