class Solution:
    def minPath(self, grid, k):
        # Initialize the result list with the first row of the grid
        res = [[grid[0][i]] for i in range(len(grid[0]))]

        # Iterate over the remaining rows of the grid
        for r in range(1, len(grid)):
            new_res = []

            # For each column in the current row, check all possible moves
            for c in range(len(grid[r])):
                for i in range(k):
                    # If the next cell has not been visited yet, add its value to the result list
                    if res[c][i] == None or res[c][i] > grid[r][c]:
                        new_res.append(res[c][i])

            # Update the result list with the new values obtained from the current row
            res = new_res

        return res

